/**
 * Check the format of keys generated by Commerce: eight uppercase groups of
 * four hexadecimal characters. This is only a format check. Imported keys
 * may use other formats, and only the server can establish validity.
 *
 * @example
 * ```ts
 * if (isGeneratedLicenseKeyFormat(key)) {
 *   // The shape matches Commerce-issued keys; validate with the API before use.
 * }
 * ```
 */
export function isGeneratedLicenseKeyFormat(value: string): boolean {
  return /^[0-9A-F]{4}(?:-[0-9A-F]{4}){7}$/.test(value);
}
